CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "role" TEXT NOT NULL DEFAULT 'CANDIDATE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Resume" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "fileName" TEXT NOT NULL, "text" TEXT NOT NULL, "skills" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Question" ("id" TEXT PRIMARY KEY, "prompt" TEXT NOT NULL, "category" TEXT NOT NULL, "difficulty" TEXT NOT NULL, "type" TEXT NOT NULL, "options" JSONB NOT NULL, "answerIndex" INTEGER NOT NULL, "explanation" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT TRUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Attempt" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "category" TEXT NOT NULL, "role" TEXT NOT NULL, "difficulty" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'IN_PROGRESS', "score" INTEGER, "deadline" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AttemptQuestion" ("id" TEXT PRIMARY KEY, "attemptId" TEXT NOT NULL REFERENCES "Attempt"("id") ON DELETE CASCADE, "position" INTEGER NOT NULL, "prompt" TEXT NOT NULL, "type" TEXT NOT NULL, "options" JSONB NOT NULL, "answerIndex" INTEGER NOT NULL, "explanation" TEXT NOT NULL, UNIQUE("attemptId", "position"));
CREATE TABLE "Response" ("id" TEXT PRIMARY KEY, "attemptId" TEXT NOT NULL REFERENCES "Attempt"("id") ON DELETE CASCADE, "questionId" TEXT NOT NULL REFERENCES "AttemptQuestion"("id") ON DELETE CASCADE, "answer" TEXT NOT NULL, "correct" BOOLEAN NOT NULL DEFAULT FALSE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("attemptId", "questionId"));
CREATE INDEX "Attempt_userId_status_createdAt_idx" ON "Attempt"("userId", "status", "createdAt");
